fn setup_status_label(status: &ManagedSetupStatus) -> &'static str {
    match status {
        ManagedSetupStatus::Ready => "Ready",
        ManagedSetupStatus::RuntimeNotInstalled => "Runtime not installed",
        ManagedSetupStatus::WslDistributionMissing => "WSL2 prerequisite not provisioned",
        ManagedSetupStatus::RestartRequired => "Windows restart required",
        ManagedSetupStatus::OperatingSystemPrerequisiteUnavailable(_) => "Prerequisite unavailable",
    }
}

fn short_digest(digest: &str) -> String {
    let prefix = digest.chars().take(16).collect::<String>();
    format!("sha256:{prefix}…")
}

fn format_bytes(bytes: u64) -> String {
    const KIB: f64 = 1024.0;
    const MIB: f64 = KIB * 1024.0;
    const GIB: f64 = MIB * 1024.0;
    let bytes_f64 = bytes as f64;
    if bytes_f64 >= GIB {
        format!("{:.2} GiB", bytes_f64 / GIB)
    } else if bytes_f64 >= MIB {
        format!("{:.1} MiB", bytes_f64 / MIB)
    } else if bytes_f64 >= KIB {
        format!("{:.1} KiB", bytes_f64 / KIB)
    } else {
        format!("{bytes} B")
    }
}
